// Refuse anything that did not come from LP MCP (shared secret, fail-closed).
const item = $input.first().json;
const hdr = (item.headers || {})['x-dnc-lift-secret'] || '';
const want = $env.DNC_LIFT_WEBHOOK_SECRET || '';
if (!want || hdr !== want) { console.log('DNC-LIFT review refused: bad or missing X-DNC-Lift-Secret'); return []; }
const r = item.body || {};
if (!r.request_id || !r.ghl_contact_id) return [];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = r.reentered_at ? new Date(r.reentered_at).toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'medium', timeStyle: 'short' }) + ' ET' : 'unknown';
const trig = r.trigger === 'reentry' ? 'Came back (re-entry)' : 'Manual review request (dnc-lift:request tag)';
const events = (r.last_consent_events || []).map(e =>
  `• ${esc(e.created_at ? String(e.created_at).slice(0, 10) : '')} ${esc(e.channel)} ${esc(e.change)} — ${esc(e.source)} (${esc(e.actor)})`).join('\n') || '• none recorded yet';
const lines = [
  `*${esc(r.contact_name)}* · phone ending *${esc(r.phone_last4 || '????')}*`,
  `*Source:* ${esc(r.source || 'unknown')}${r.sub_source ? ' / ' + esc(r.sub_source) : ''}`,
  `*Why we are looking:* ${trig} · ${when}`,
  `*Blocked by:* ${(r.blocking_tags || []).map(t => '`' + esc(t) + '`').join(' ') || 'none'}`,
  `*Recent consent history:*\n${events}`,
  `<${r.ghl_contact_url}|Open in GHL>`,
];
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'DNC lift review' } },
  { type: 'section', text: { type: 'mrkdwn', text: lines.join('\n').slice(0, 2900) } },
];
if (r.sms_carrier_stop) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ':warning: *' + esc(r.sms_warning || 'This lead texted STOP. Approving restores calls only. Texts stay off until they text START or submit a new form with SMS consent.') + '*' } });
}
const value = JSON.stringify({ request_id: r.request_id, ghl_contact_id: r.ghl_contact_id });
blocks.push({ type: 'actions', block_id: 'dnc_lift_actions', elements: [
  { type: 'button', action_id: 'dnc_lift_approve', style: 'primary', text: { type: 'plain_text', text: '✅ Approve Lift' }, value,
    confirm: { title: { type: 'plain_text', text: 'Lift DNC?' },
      text: { type: 'mrkdwn', text: r.sms_carrier_stop ? 'Restores calls, LP and Five9. Texts stay OFF.' : 'Restores calls, texts, email, LP and Five9.' },
      confirm: { type: 'plain_text', text: 'Lift it' }, deny: { type: 'plain_text', text: 'Cancel' } } },
  { type: 'button', action_id: 'dnc_lift_keep_blocked', style: 'danger', text: { type: 'plain_text', text: '⛔ Keep Blocked' }, value },
]});
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `request ${esc(r.request_id)}` }] });
return [{ json: {
  text: `DNC lift review: ${r.contact_name} (…${r.phone_last4 || '????'})${r.sms_carrier_stop ? ' — texted STOP, calls only' : ''}`,
  blocks,
}}];

// Prefer an explicit channel id; else the channel we just created (the bot is
// then a member); else the name, which works once someone has created the
// channel and invited the bot. name_taken / missing_scope land here too.
const card = $('Build Card').first().json;
const res = $input.first().json || {};
const channel = $env.SLACK_DNC_LIFT_CHANNEL_ID || (res.ok && res.channel && res.channel.id) || '#dnc-lift-approval';
return [{ json: { ...card, channel } }];

const r = $input.first().json || {};
if (!r.ok) throw new Error('DNC-LIFT card did not post: ' + (r.error || 'unknown') + ' — create #dnc-lift-approval and invite the bot, or set SLACK_DNC_LIFT_CHANNEL_ID');
return [{ json: { posted: true, channel: r.channel, ts: r.ts } }];

// Only LP MCP may relay a click here: it verified Slack's signature, so the
// clicking user's id is trustworthy. Fail-closed on the forward credential.
const item = $input.first().json;
const want = $env.SLACK_INTERACTIONS_FORWARD_AUTH || '';
const got = (item.headers || {})['x-lpmcp-forward-auth'] || '';
if (!want || got !== want) { console.log('DNC-LIFT click refused: bad or missing X-LPMCP-Forward-Auth'); return []; }
let p = (item.body || {}).payload;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = null; } }
if (!p || p.type !== 'block_actions') return [];
const a = (p.actions || [])[0] || {};
const decision = a.action_id === 'dnc_lift_approve' ? 'approve' : a.action_id === 'dnc_lift_keep_blocked' ? 'keep_blocked' : null;
if (!decision) return [];
let v = {};
try { v = JSON.parse(a.value || '{}'); } catch (e) {}
if (!v.request_id || !v.ghl_contact_id || !(p.user && p.user.id)) return [];
const keep = ((p.message && p.message.blocks) || []).filter(b => b.type !== 'actions');
return [{ json: {
  decision, request_id: v.request_id, ghl_contact_id: v.ghl_contact_id,
  slack_user_id: p.user.id, slack_user_name: p.user.name || p.user.username || p.user.id,
  slack_ts: (p.message && p.message.ts) || (p.container && p.container.message_ts) || '',
  channel: (p.channel && p.channel.id) || (p.container && p.container.channel_id) || '',
  response_url: p.response_url || '', card_blocks: keep,
}}];

const c = $('Parse Click').first().json;
const resp = $input.first().json || {};
const code = resp.statusCode || 0;
const r = resp.body && typeof resp.body === 'object' ? resp.body : {};
const mark = $env.DNC_LIFT_ESCALATE_SLACK_ID || 'U0BU7TZPY82';
const at = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'medium', timeStyle: 'short' }) + ' ET';
const decision = r.decision || c.decision;
const by = r.idempotent && r.decided_by ? r.decided_by : '<@' + c.slack_user_id + '>';
let headline = decision === 'approve' ? `✅ Approved by ${by} at ${at}` : `⛔ Kept blocked by ${by} at ${at}`;
if (r.idempotent) headline = (decision === 'approve' ? '✅ Already approved' : '⛔ Already kept blocked') + ` by ${by}`;

const label = { ghl: 'GHL', lp: 'LP', five9: 'Five9', consent: 'Consent record', audit: 'Audit event' };
const sys = r.systems || {};
const rows = Object.keys(label).filter(k => sys[k]).map(k =>
  `• ${label[k]}: ${sys[k].status === 'failed' ? '❌ failed — ' + (sys[k].errors || []).join('; ').slice(0, 400) : '✅ done'}`);
let failed = code < 200 || code >= 300 || r.ok === false;
let lines = [];
if (code >= 200 && code < 300) {
  lines.push(decision === 'approve' ? '*Lift result*' : '*Keep-blocked result*');
  lines.push(...(rows.length ? rows : ['• (no per-system detail returned)']));
  if (r.sms_warning) lines.push(':warning: ' + r.sms_warning);
  if (r.idempotent) lines.push('_This request was already decided — nothing was run again._');
} else {
  lines.push(`❌ LP MCP refused or failed (HTTP ${code}): ${String(r.error || (r.errors || []).join('; ') || resp.body || 'no response').slice(0, 400)}`);
}
if (failed) lines.push(`<@${mark}> something did not complete — please check this lead.`);
return [{ json: {
  response_url: c.response_url, channel: c.channel, thread_ts: c.slack_ts,
  card: { replace_original: true, text: headline, blocks: [...c.card_blocks, { type: 'context', elements: [{ type: 'mrkdwn', text: headline }] }] },
  thread_text: lines.join('\n'),
}}];
